def e(s):return html.escape(str(s),quote=True)
thumbs=OUT/'thumbnails';thumbs.mkdir(exist_ok=True)
def image_markup(rel,label):
 from PIL import Image,ImageOps
 dest=thumbs/(hashlib.sha256(rel.encode()).hexdigest()[:16]+'.jpg')
 if not dest.exists():
  with Image.open(DATA/rel) as im:
   im=ImageOps.exif_transpose(im).convert('RGB');im.thumbnail((420,420));im.save(dest,quality=84)
 return '<figure><a href="../'+e(rel)+'"><img loading="lazy" src="thumbnails/'+dest.name+'"></a><figcaption>'+e(label)+'</figcaption></figure>'

def editor(row,title,extra='',kind='templates'):
 refs=' · '.join('<a href="#'+e(h)+'">'+e(h)+'</a>' if h.startswith('H') else e(h) for h in row.get('sources',[]))
 return '<article class="editable" data-id="'+e(row['id'])+'" data-kind="'+kind+'"><h2>'+e(title)+'</h2>'+extra+'<p class="source">Sources: '+refs+'</p><p>'+e(row.get('notes',''))+'</p><label>Proposed standalone prompt<textarea spellcheck="false">'+e(row['prompt'])+'</textarea></label><div class="controls"><label>Decision <select class="decision"><option value="pending">Pending</option><option value="approved">Approve</option><option value="changes_requested">Needs changes</option><option value="excluded">Exclude</option></select></label><input class="review-note" placeholder="Your review notes"><button class="reset-prompt">Restore draft</button></div></article>'
sections=[]
sections.append('<section id="templates" class="tab-panel"><h1>Shared instructions</h1><p>Review these first. The final style combines the later shading corrections. Exceptions remain local.</p>'+''.join(editor(x,x['id']+' · '+x['title']) for x in styles)+'</section>')
